//! Sample-exact mixer golden for `examples/demo.motioner`.
//!
//! The demo music is a committed PCM WAV generated by ffmpeg's `aevalsrc`
//! source. Decoding it to the cache and mixing the first 4096 stereo frames
//! must stay bit-identical: the hash pins the asset, the project path and the
//! deterministic mixer in one check.

use std::collections::HashSet;
use std::fmt::Write as _;
use std::path::Path;

use motioner_io::{
    decode_to_cache, mix_document, AudioStore, FfmpegLocation, Project, SAMPLE_RATE,
};
use sha2::{Digest, Sha256};

const MIXED_SHA: &str = "692426df8f4c1d703cc06f75fdd23c8e3dafe41f2e7c4ee2bbc13eab682e5772";

fn project_root() -> &'static Path {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .and_then(Path::parent)
        .expect("crates/motioner_io has a workspace root")
}

fn hex(bytes: &[u8]) -> String {
    let mut text = String::with_capacity(bytes.len() * 2);
    for byte in bytes {
        write!(&mut text, "{byte:02x}").expect("writing to a String cannot fail");
    }
    text
}

#[test]
fn the_demo_mix_is_sample_exact() {
    let project = Project::open(&project_root().join("examples/demo.motioner")).unwrap();
    let source = std::fs::read_to_string(project.composition_path("main")).unwrap();
    let document =
        motioner_dsl::run(&source, &motioner_dsl::Limits::default()).expect("the demo compiles");
    let entry = project
        .find_asset("music.wav")
        .expect("the demo music asset");
    let path = project.assets_dir().join(entry.file_name());
    let pcm = decode_to_cache(
        &path,
        &project.cache_dir(),
        &entry.hash,
        &FfmpegLocation::FromEnvOrPath,
    )
    .expect("the demo music decodes");
    assert_eq!(pcm.sample_rate, SAMPLE_RATE);
    let mut store = AudioStore::default();
    store.insert(entry.key.clone(), pcm.clone());
    store.insert(entry.original.clone(), pcm);

    let mixed = mix_document(&document, &store, 0, 4096, &HashSet::new());
    assert_eq!(mixed.len(), 4096 * 2);
    assert!(
        mixed.iter().any(|sample| *sample != 0.0),
        "the demo music must not mix to silence"
    );
    let mut hasher = Sha256::new();
    for sample in &mixed {
        hasher.update(sample.to_le_bytes());
    }
    let actual = hex(&hasher.finalize());
    assert_eq!(
        actual, MIXED_SHA,
        "the demo mix changed; update MIXED_SHA to {actual}"
    );
}
